const std::string& getName() const { return name_; }
// Polymorphic method
virtual void display() const = 0;
private:
std::string name_;
};
// Derived class for painting exhibits class Painting : public Exhibit
{
public:
Painting(const std::string& name, const std::string& artist) : Exhibit(name), artist_(artist) {}
